public static String longestCommonSubsequence(String s1,String s2) {
   int l1 = s1.length();
   int l2 = s2.length();

   int[][] aux = new int[l1+1][l2+1];
   for (int i = 0; i < l1; i++) {
      for (int j = 0; j < l2; j++) {
         if (s1.charAt(i) == s2.charAt(j))
            aux[i+1][j+1] = aux[i][j] + 1;
         else
            aux[i+1][j+1] = Math.max(aux[i+1][j], aux[i][j+1]);
      }
   }
   StringBuilder sb = new StringBuilder();
   for (int i = l1, j = l2; i != 0 && j != 0; ) {
      if (aux[i][j] == aux[i-1][j])
         i--;
      else if (aux[i][j] == aux[i][j-1])
         j--;
      else {
         sb.append(s1.charAt(i-1));
         i--;
         j--;
      }
   }
   return sb.reverse().toString();
}

fn lowestCommonAncestor(root: &TreeNode, p: &TreeNode, q: &TreeNode) -> i32 {
 if root == nil {
  return -1;
 }

 if root == p || root == q {
  return root.val;
 }

 let left = lowestCommonAncestor(root.left, p, q);
 let right = lowestCommonAncestor(root.right, p, q);

 if left != -1 && right != -1 {
  return root.val;
 }

 return left != -1 ? left : right;
}

